import os
os.environ["POLARS_MAX_THREADS"]="2"
os.environ["POLARS_UNKNOWN_EXTENSION_TYPE_BEHAVIOR"]="load_as_storage"
import polars as pl, glob
pl.Config.set_tbl_rows(100); pl.Config.set_tbl_cols(40); pl.Config.set_tbl_width_chars(300)
R="/home/user/prc-data-challenge/data/raw/"
rank=pl.scan_parquet(R+"ranking.parquet")
tr=pl.scan_parquet(sorted(glob.glob(R+"training_*.parquet")))
sec=lambda a,b:(pl.col(a)-pl.col(b)).dt.total_seconds()
band=lambda: pl.when(pl.col("ms")<-3600).then(pl.lit("a:<-1h")).when(pl.col("ms")<7200).then(pl.lit("b:normal")).when(pl.col("ms")<14400).then(pl.lit("c:2-4h")).when(pl.col("ms")<72000).then(pl.lit("d:4-20h")).when(pl.col("ms")<100800).then(pl.lit("e:20-28h")).otherwise(pl.lit("f:>28h")).alias("band")
dep=tr.filter(pl.col("PHASE_mvt")=="DEP").with_columns([pl.col("FLIGHT_ID_mvt").is_null().alias("unm"),sec("MVT_TIME_UTC_mvt","SCHED_TIME_UTC_mvt").alias("ms"),sec("BLOCK_TIME_UTC_mvt","SCHED_TIME_UTC_mvt").alias("bs"),sec("AOBT_3_flt","SCHED_TIME_UTC_mvt").alias("as_"),pl.col("TAXITIME_SEC_mvt").alias("y")]).with_columns([band(),(pl.col("bs").abs()<=10).alias("fill"),((pl.col("y")-pl.col("ms")).abs()<=60).alias("y_eq_ms"),(pl.col("y")>=7200).alias("y_big")])
rk=rank.filter(pl.col("PHASE_mvt")=="DEP").with_columns([pl.col("FLIGHT_ID_mvt").is_null().alias("unm"),sec("MVT_TIME_UTC_mvt","SCHED_TIME_UTC_mvt").alias("ms")]).with_columns(band())
print("=== I. MVT-SCHED band x matched: training label behaviour, and ranking counts ===")
t=dep.group_by(["band","unm"]).agg([pl.len().alias("n_train"),pl.col("fill").mean().round(3).alias("blk_fill_rate"),pl.col("y_eq_ms").mean().round(3).alias("y_eq_mvt_sched"),pl.col("y_big").mean().round(3).alias("y_ge2h"),pl.col("y").median().alias("y_med"),pl.col("y").std().round(0).alias("y_sd")]).collect()
r=rk.group_by(["band","unm"]).agg(pl.len().alias("n_rank")).collect()
print(t.join(r,on=["band","unm"],how="full",coalesce=True).sort(["band","unm"]))
print("=== I2. same, restricted to bands c/d, per airport ===")
t2=dep.filter(pl.col("band").is_in(["c:2-4h","d:4-20h"])).group_by(["ADEP_mvt","unm"]).agg([pl.len().alias("n_train"),pl.col("fill").mean().round(2).alias("fill"),pl.col("y_eq_ms").mean().round(2).alias("y_eq_ms"),pl.col("y_big").mean().round(2).alias("y_ge2h"),pl.col("y").median().alias("y_med")]).collect()
r2=rk.filter(pl.col("band").is_in(["c:2-4h","d:4-20h"])).group_by(["ADEP_mvt","unm"]).agg(pl.len().alias("n_rank")).collect()
print(t2.join(r2,on=["ADEP_mvt","unm"],how="full",coalesce=True).sort(["ADEP_mvt","unm"]))
print("=== I3. training: y>=7200 rows — fraction explained as y≈ms or y≈ms+86400 or y≈normal+86400 ===")
big=dep.filter(pl.col("y")>=7200).with_columns([((pl.col("y")-pl.col("ms")).abs()<=60).alias("eq_ms"),(((pl.col("y")-pl.col("ms")).abs()<=60)|((pl.col("y")-pl.col("ms")-86400).abs()<=60)|((pl.col("y")-pl.col("ms")+86400).abs()<=60)).alias("eq_ms_pm_day"),(((pl.col("y")-86400)>0)&((pl.col("y")-86400)<3600)).alias("day_plus_taxi")])
print(big.group_by("unm").agg([pl.len(),pl.col("eq_ms").mean().round(3),pl.col("eq_ms_pm_day").mean().round(3),pl.col("day_plus_taxi").mean().round(3),pl.col("fill").mean().round(3)]).collect())
print("=== J. LIRF matched rows: is BLOCK≈SCHED fill predictable? rate by hour_utc, by operator (top), by |AOBT-SCHED| bucket ===")
l=dep.filter((pl.col("ADEP_mvt")=="LIRF")&(~pl.col("unm"))).with_columns([pl.col("MVT_TIME_UTC_mvt").dt.hour().alias("h"),pl.col("MVT_TIME_UTC_mvt").dt.month().alias("mo"),(pl.col("as_").abs()>600).alias("aobt_far_from_sched")])
print(l.group_by("aobt_far_from_sched").agg([pl.len(),pl.col("fill").mean().round(3).alias("fill_rate"),pl.col("y").filter(pl.col("fill")).std().alias("y_sd_fill"),(pl.col("y")-sec("MVT_TIME_UTC_mvt","AOBT_3_flt")).filter(pl.col("fill")).std().alias("resid_sd_fill")]).collect())
print(l.group_by("mo").agg([pl.len(),pl.col("fill").mean().round(3).alias("fill_rate")]).sort("mo").collect())
print(l.group_by("h").agg([pl.len(),pl.col("fill").mean().round(3).alias("fill_rate")]).sort("h").collect().transpose(include_header=True))
print(l.group_by("AIRCRAFT_OPERATOR_flt").agg([pl.len(),pl.col("fill").mean().round(3).alias("fill_rate")]).filter(pl.col("len")>2000).sort("fill_rate",descending=True).collect().head(12))
print(l.group_by("MARKET_SEGMENT_flt").agg([pl.len(),pl.col("fill").mean().round(3).alias("fill_rate")]).sort("len",descending=True).collect())
print("LIRF unmatched fill rate by month:")
print(dep.filter((pl.col("ADEP_mvt")=="LIRF")&pl.col("unm")).group_by(pl.col("MVT_TIME_UTC_mvt").dt.month().alias("mo")).agg([pl.len(),pl.col("fill").mean().round(3).alias("fill_rate"),pl.col("y_big").mean().round(3).alias("y_ge2h"),pl.col("ms").median().alias("ms_med")]).sort("mo").collect())
print("=== K. EHAM Jan 2026 vs Jan 2025: per-day unmatched count and proxy sd ===")
def eham(lf,tag):
    return lf.filter((pl.col("PHASE_mvt")=="DEP")&(pl.col("ADEP_mvt")=="EHAM")&(pl.col("MVT_TIME_UTC_mvt").dt.month()==1)).with_columns([sec("MVT_TIME_UTC_mvt","AOBT_3_flt").alias("proxy"),pl.col("MVT_TIME_UTC_mvt").dt.day().alias("d")]).group_by("d").agg([pl.len().alias("n"),pl.col("FLIGHT_ID_mvt").is_null().sum().alias("n_unm"),pl.col("proxy").std().round(0).alias("proxy_sd"),pl.col("proxy").median().alias("proxy_med"),(pl.col("AOBT_3_flt").dt.second()==0).mean().round(2).alias("aobt_round")]).sort("d").with_columns(pl.lit(tag).alias("src"))
e=pl.concat([eham(tr,"2025").collect(),eham(rank,"2026").collect()])
print(e.pivot(on="src",index="d",values=["n_unm","proxy_sd","aobt_round"]).sort("d"))
wx=pl.read_parquet("/home/user/prc-data-challenge/data/ref/metar_hourly.parquet").filter(pl.col("station")=="EHAM")
print(wx.group_by(pl.col("hour_utc").dt.strftime("%Y-%m").alias("ym")).agg([pl.col("deicing_gate").mean().round(3),pl.col("frozen_wx").mean().round(3),pl.col("low_vis").mean().round(3),pl.col("temp_c").mean().round(1)]).filter(pl.col("ym").is_in(["2025-01","2025-07","2026-01","2026-07"])).sort("ym"))
wxa=pl.read_parquet("/home/user/prc-data-challenge/data/ref/metar_hourly.parquet")
print(wxa.group_by(["station",pl.col("hour_utc").dt.strftime("%Y-%m").alias("ym")]).agg([pl.col("deicing_gate").mean().round(3).alias("deice"),pl.col("low_vis").mean().round(3).alias("lowvis")]).filter(pl.col("ym").is_in(["2025-01","2026-01"])).pivot(on="ym",index="station",values=["deice","lowvis"]).sort("station"))
print("=== L. duplicate DEP pairs (same ADEP, FLIGHT, SCHED): label ordering ===")
g=dep.filter(pl.col("FLIGHT_mvt").is_not_null()).with_columns(pl.len().over(["ADEP_mvt","FLIGHT_mvt","SCHED_TIME_UTC_mvt"]).alias("k")).filter(pl.col("k")==2).sort(["ADEP_mvt","FLIGHT_mvt","SCHED_TIME_UTC_mvt","MVT_TIME_UTC_mvt"]).collect()
pairs=g.group_by(["ADEP_mvt","FLIGHT_mvt","SCHED_TIME_UTC_mvt"]).agg([pl.col("unm").first().alias("unm1"),pl.col("unm").last().alias("unm2"),pl.col("y").first().alias("y1"),pl.col("y").last().alias("y2"),(pl.col("MVT_TIME_UTC_mvt").last()-pl.col("MVT_TIME_UTC_mvt").first()).dt.total_seconds().alias("dt")])
print("pairs:",pairs.height); print(pairs.group_by(["unm1","unm2"]).agg([pl.len(),(pl.col("dt")<=120).mean().round(2).alias("same_takeoff"),pl.col("y1").median().alias("y1_med"),pl.col("y2").median().alias("y2_med"),(pl.col("y1")>pl.col("y2")).mean().round(2).alias("y1_gt_y2"),pl.max_horizontal("y1","y2").median().alias("ymax_med")]))
mixed=pairs.filter(pl.col("unm1")!=pl.col("unm2")).with_columns(pl.when(pl.col("unm1")).then(pl.col("y1")).otherwise(pl.col("y2")).alias("y_unm"),pl.when(pl.col("unm1")).then(pl.col("y2")).otherwise(pl.col("y1")).alias("y_m"))
print("mixed pairs: unmatched label > matched label rate:",(mixed["y_unm"]>mixed["y_m"]).mean(),"n",mixed.height,"median y_unm",mixed["y_unm"].median(),"median y_m",mixed["y_m"].median())
rg=rk.filter(pl.col("FLIGHT_mvt").is_not_null()).with_columns(pl.len().over(["ADEP_mvt","FLIGHT_mvt","SCHED_TIME_UTC_mvt"]).alias("k")).filter(pl.col("k")>=2).collect()
print("ranking dup rows:",rg.height, rg.group_by(["ADEP_mvt"]).agg([pl.len(),pl.col("unm").mean().round(2)]).sort("len",descending=True))
print("=== M. submission files: count of predictions >= 7200 / >= 43200 ===")
for f in sorted(glob.glob("/home/user/prc-data-challenge/outputs/*.parquet")):
    s=pl.read_parquet(f)
    print(os.path.basename(f), s.height, "ge2h",(s["TAXITIME_SEC_mvt"]>=7200).sum(),"ge12h",(s["TAXITIME_SEC_mvt"]>=43200).sum(),"max",s["TAXITIME_SEC_mvt"].max())
print("training label: ge2h",dep.select((pl.col("y")>=7200).sum()).collect().item(),"ge12h",dep.select((pl.col("y")>=43200).sum()).collect().item(),"of",dep.select(pl.len()).collect().item())
